/*
 * SPDX-License-Identifier: AGPL-3.0-only
 *
 * The pinned Audacity 4 action inventory.
 *
 * This table is the contract itself, and it is intentionally pinned: updating
 * it means reviewing the upstream menus and action registrations at the new
 * commit, not merely changing AUDACITY_ACTION_SOURCE.commit. It sits apart from
 * the parity runtime that reads it so that the inventory stays a list, and the
 * code that resolves, localizes and decorates entries stays readable beside it.
 * A definition's `shortcut` is also the immutable pre-profile default used to
 * recognize untouched saved preferences; imported live defaults are separate.
 */

import {
	AUDACITY_DISABLED_REASONS as DISABLED_REASONS,
	AUDACITY_EXCLUDED_REASONS as EXCLUDED_REASONS,
} from '../i18n/action-parity.js';
import { createAudacityActionDefinition as actionDefinition } from './audacity-action-roadmap.ts';
import { NYQUIST_BUNDLED_PLUGINS } from './nyquist/plugin-registry.js';

export const AUDACITY_ACTION_STATUS = Object.freeze({
	IMPLEMENTED: 'implemented',
	DISABLED_UPSTREAM: 'disabled-upstream',
	EXCLUDED: 'excluded',
});

const UPSTREAM = Object.freeze({
	application: 'src/appshell/internal/applicationuiactions.cpp',
	menu: 'src/appshell/qml/Audacity/AppShell/appmenumodel.cpp',
	project: 'src/project/internal/projectuiactions.cpp',
	trackEdit: 'src/trackedit/internal/trackedituiactions.cpp',
	projectScene: 'src/projectscene/internal/projectsceneuiactions.cpp',
	playback: 'src/playback/internal/playbackuiactions.cpp',
	record: 'src/record/internal/recorduiactions.cpp',
	effects: 'src/effects/effects_base/internal/effectsuiactions.cpp',
	builtinEffects: 'src/effects/builtin_collection/internal/builtincollectionloader.cpp',
	spectrogram: 'src/spectrogram/internal/spectrogramuiactions.cpp',
});

const implemented = (id, label, locations, handler, options = {}) => actionDefinition({
	id,
	label,
	locations,
	handler,
	enableWhen: options.enableWhen || 'always',
	shortcut: options.shortcut ?? null,
	status: AUDACITY_ACTION_STATUS.IMPLEMENTED,
	upstreamAction: options.upstreamAction || id,
	upstreamSource: options.source === undefined ? UPSTREAM.project : options.source,
	origin: options.origin || 'upstream',
	menuVisible: options.menuVisible !== false,
});

const disabled = (id, label, locations, reason = DISABLED_REASONS.menu, options = {}) => actionDefinition({
	id,
	label,
	locations,
	handler: null,
	enableWhen: 'never',
	shortcut: options.shortcut ?? null,
	status: AUDACITY_ACTION_STATUS.DISABLED_UPSTREAM,
	upstreamAction: options.upstreamAction || id,
	upstreamSource: options.source === undefined ? UPSTREAM.menu : options.source,
	origin: options.origin || 'upstream',
	reason,
	menuVisible: options.menuVisible !== false,
});

const excluded = (id, label, locations, reason, options = {}) => actionDefinition({
	id,
	label,
	locations,
	handler: null,
	enableWhen: 'never',
	shortcut: options.shortcut ?? null,
	status: AUDACITY_ACTION_STATUS.EXCLUDED,
	upstreamAction: options.upstreamAction || id,
	upstreamSource: options.source === undefined ? UPSTREAM.project : options.source,
	origin: options.origin || 'upstream',
	reason,
});

const legacyMixer = (id, label, enableWhen, location = 'Track context') => implemented(
	id, label, [location], 'track.audacityMixer',
	{ enableWhen, source: 'au3/src/menus/TrackMenus.cpp' },
);

const labeledAudio = (id, label, handler, shortcut, upstreamAction) => implemented(
	id, label, ['Edit > Labeled audio'], handler,
	{ enableWhen: 'editable-labeled-audio', shortcut, source: 'au3/src/menus/LabelMenus.cpp', upstreamAction },
);

const labeledAudioDefinitions = [
	labeledAudio('cut-labels', 'Cut labeled audio', 'edit.labeledCut', 'Alt+X', 'CutLabels'),
	labeledAudio('delete-labels', 'Delete labeled audio', 'edit.labeledDelete', 'Alt+K', 'DeleteLabels'),
	labeledAudio('split-cut-labels', 'Cut labeled audio and leave gap', 'edit.labeledCutLeaveGap', 'Alt+Shift+X', 'SplitCutLabels'),
	labeledAudio('split-delete-labels', 'Delete labeled audio and leave gap', 'edit.labeledDeleteLeaveGap', 'Alt+Shift+K', 'SplitDeleteLabels'),
	labeledAudio('silence-labels', 'Silence labeled audio', 'edit.labeledSilence', 'Alt+L', 'SilenceLabels'),
	labeledAudio('copy-labels', 'Copy labeled audio', 'edit.labeledCopy', 'Alt+Shift+C', 'CopyLabels'),
	labeledAudio('split-labels', 'Split labeled audio', 'edit.labeledSplit', 'Alt+I', 'SplitLabels'),
	labeledAudio('join-labels', 'Join labeled audio', 'edit.labeledJoin', 'Alt+J', 'JoinLabels'),
	labeledAudio('disjoin-labels', 'Detach labeled audio at silences', 'edit.labeledDisjoin', 'Alt+Shift+J', 'DisjoinLabels'),
];

const nyquistDefinitions = NYQUIST_BUNDLED_PLUGINS.map((plugin) => {
	const location = 'Nyquist';
	const enableWhen = plugin.spectral
		? 'editable-frequency-selection'
		: plugin.category === 'generate' ? 'project-writable'
			: plugin.category === 'legacy' ? 'editable-selection-or-clip' : 'audio-selection-or-clip';
	return implemented(plugin.id, plugin.name, [location], `nyquist.plugins.${plugin.id}`, {
		enableWhen,
		source: `plug-ins/${plugin.fileName}`,
		upstreamAction: plugin.fileName,
	});
});

